import { useState, type FormEvent } from 'react'

import type { NewExpense, SubmitExpenseResult } from '../../application/ExpenseViewModel'

type ExpenseFormProps = { onSubmit: (expense: NewExpense) => Promise<SubmitExpenseResult> }

export const ExpenseForm = ({ onSubmit }: ExpenseFormProps) => {
  const [label, setLabel] = useState('')
  const [amount, setAmount] = useState('')
  const [currency, setCurrency] = useState('EUR')
  const [errors, setErrors] = useState<Record<string, string>>({})
  const [failure, setFailure] = useState<string | null>(null)
  const [pending, setPending] = useState(false)

  const handleSubmit = async (event: FormEvent) => {
    event.preventDefault()
    setPending(true)
    setFailure(null)
    try {
      const result = await onSubmit({ label, amount: Number(amount), currency })
      if (result.ok) {
        setErrors({})
        setLabel('')
        setAmount('')
      } else {
        setErrors(result.errors)
      }
    } catch (error) {
      setFailure(error instanceof Error ? error.message : 'Could not submit the expense')
    } finally {
      setPending(false)
    }
  }

  return (
    <form onSubmit={handleSubmit} noValidate>
      <div>
        <label htmlFor="expense-label">Label</label>
        <input
          id="expense-label"
          value={label}
          onChange={(e) => setLabel(e.target.value)}
          aria-invalid={Boolean(errors.label)}
          aria-describedby={errors.label ? 'expense-label-error' : undefined}
        />
        {errors.label && <p id="expense-label-error" role="alert">{errors.label}</p>}
      </div>
      <div>
        <label htmlFor="expense-amount">Amount</label>
        <input
          id="expense-amount"
          type="number"
          step="0.01"
          value={amount}
          onChange={(e) => setAmount(e.target.value)}
          aria-invalid={Boolean(errors.amount)}
          aria-describedby={errors.amount ? 'expense-amount-error' : undefined}
        />
        {errors.amount && <p id="expense-amount-error" role="alert">{errors.amount}</p>}
      </div>
      <div>
        <label htmlFor="expense-currency">Currency</label>
        <input
          id="expense-currency"
          value={currency}
          onChange={(e) => setCurrency(e.target.value)}
          aria-invalid={Boolean(errors.currency)}
          aria-describedby={errors.currency ? 'expense-currency-error' : undefined}
        />
        {errors.currency && <p id="expense-currency-error" role="alert">{errors.currency}</p>}
      </div>
      {failure && <p role="alert">{failure}</p>}
      <button type="submit" disabled={pending}>Submit expense</button>
    </form>
  )
}
